def find_median(a, b):
    merged = sorted(a + b)
    n = len(merged)
    mid = n // 2
    if n % 2 == 1:
        return float(merged[mid])
    return (merged[mid - 1] + merged[mid]) / 2.0

solutions.javascript:
function findMedian(a, b) {
  const merged = [...a, ...b].sort((x, y) => x - y);
  const n = merged.length;
  const mid = Math.floor(n / 2);
  return n % 2 === 1 ? merged[mid] : (merged[mid - 1] + merged[mid]) / 2;
}

solutions.cpp:
double findMedian(std::vector<long long> a, std::vector<long long> b) {
    std::vector<long long> merged;
    merged.reserve(a.size() + b.size());
    merged.insert(merged.end(), a.begin(), a.end());
    merged.insert(merged.end(), b.begin(), b.end());
    std::sort(merged.begin(), merged.end());
    std::size_t n = merged.size();
    std::size_t mid = n / 2;
    if (n % 2 == 1) return (double)merged[mid];
    return ((double)merged[mid - 1] + (double)merged[mid]) / 2.0;
}
